import{_ as r,l as h,o as e,c as o,v as c,p as s,x as i,d as n,i as l,S as b}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"bcache","description":"","frontmatter":{"title":"bcache","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bcache.md","filePath":"cs/bcache.md","lastUpdated":1789023840000}'),d={name:"cs/bcache.md"};function p(D,a,m,S,_,u){const t=h("Mermaid");return e(),o("div",null,[a[1]||(a[1]=c('<h1 id="bcache" tabindex="-1">bcache <a class="header-anchor" href="#bcache" aria-label="Permalink to &quot;bcache&quot;">​</a></h1><div class="epigraph"><p>bcache 用一块快设备做慢设备的块缓存：写回或写通，命中则不必再走 HDD 臂。</p><footer>—— 据 Linux bcache 文档；Kent Overstreet 对 bcache 的设计讨论</footer></div><p><a href="/cs/thin-provisioning">上一课</a>省的是容量。延迟仍可以是 HDD。<a href="/cs/page-cache">页缓存</a> 是内存；重启丢失。缺口是 <strong>块层持久缓存</strong>：bcache（及后来的 bcachefs 不在本课）把 SSD 接到 HDD 前面。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>热数据若能停在 SSD，顺序冷数据留在大盘。bcache：backing + cache 设备，注册后出现 <code>/dev/bcacheN</code>。模式：writeback（写先进缓存，标脏）与 writethrough（写双份）。缺口：缓存未命中的绕过顺序流（顺序大写可绕过以免打满 SSD）；脏数据崩溃要用缓存超级块恢复；与 <a href="/cs/device-mapper-lvm">dm</a> 的 dm-cache 是同类对象，课序以 bcache 为实例。</p><p><span class="marginnote">缓存集可服务多个 backing。丢 SSD 在 writeback 下等于丢脏数据，要用附件或接受损失。本课不把 bcachefs 文件系统写成同一课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读：查缓存桶（bucket）与 btree 索引，命中则从 SSD 填 bio，否则读 HDD 并可提升。写 writeback：写 SSD，完成上层，稍后回写 HDD。对照 FS 预读：预读仍发生在 bcache 之上或之下，取决于谁看到顺序。对照 RAID：缓存不是冗余。</p>',8)),(e(),s(b,null,{default:i(()=>[l(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIO%5B%22bio%22%5D%20--%3E%20BC%5B%22bcache%22%5D%0A%20%20BC%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20SSD%5B%22%E7%BC%93%E5%AD%98%E7%9B%98%22%5D%0A%20%20BC%20--%3E%7C%22bypass%2Fmiss%22%7C%20HDD%5B%22backing%22%5D%0A%20%20WB%5B%22writeback%20%E8%84%8F%22%5D%20--%3E%20HDD%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=c('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>bcache 把「存储分层」放进块层，FS 无需知道。它与 CPU cache 同构只在「命中/缺失」口号上；一致性是脏桶与回写，不是 MESI。不要写成硬件预取课。与 <a href="/cs/thin-provisioning">精简</a>：可叠，监控更乱。</p><p>错误：缓存只读降级、只通盘，是运维模式；课序要求理解脏数据依赖缓存盘。</p><p>实现上：writeback 模式丢缓存盘等于丢尚未回写的数据，要按电池或副本设计。顺序绕过阈值调错会让 SSD 被大备份打满，命中率崩。 读法上只引用<a href="/cs/thin-provisioning">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「存储栈 / 块层到设备」课序里，对象是 <strong>bcache</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 EnhanceIO、Lvmcache 的参数对照表。不保证 NVMe 对 NVMe 再套 bcache 有益。下一课缓存都不经过：DAX 把持久内存直接映射进页表。</p><p>版本字段会变，课序钉的是机制对象「bcache」，不是某一主线内核的结构体名。 后课默认：块层可用 SSD 缓存 HDD。持久内存如何绕过块层进 CPU 缓存，下一课 DAX。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>bcache 用快设备缓存慢设备；writeback 有脏。</li><li>顺序流可绕过以免污染缓存。</li><li>DAX 与持久内存是下一课。</li><li>出处：Linux bcache；dm-cache 对照；<em>OSTEP</em> I/O 栈。</li></ul>',11))])}const g=r(d,[["render",p]]);export{k as __pageData,g as default};
